CREATE TABLE saved_payment_methods (
  saved_payment_method_id TEXT PRIMARY KEY NOT NULL
    CHECK (char_length(saved_payment_method_id) = 30 AND saved_payment_method_id ~ '^spm_[A-Za-z0-9]{26}$'),
  provider TEXT NOT NULL CHECK (provider = 'hyperswitch'),
  merchant_id TEXT NOT NULL CHECK (char_length(merchant_id) BETWEEN 1 AND 256),
  customer_id TEXT NOT NULL CHECK (char_length(customer_id) BETWEEN 1 AND 256),
  payment_method_id TEXT NOT NULL
    CHECK (char_length(payment_method_id) BETWEEN 1 AND 255 AND payment_method_id ~ '^[!-~]+$'),
  source_payment_id TEXT NOT NULL
    CHECK (char_length(source_payment_id) = 30 AND source_payment_id ~ '^pay_[A-Za-z0-9]{26}$'),
  source_event_id TEXT NOT NULL CHECK (char_length(source_event_id) BETWEEN 1 AND 255),
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE (provider, merchant_id, payment_method_id)
);
CREATE INDEX ix_saved_payment_methods_customer_created
  ON saved_payment_methods(customer_id, created_at, saved_payment_method_id);

CREATE TABLE payment_mandates (
  mandate_record_id TEXT PRIMARY KEY NOT NULL
    CHECK (char_length(mandate_record_id) = 30 AND mandate_record_id ~ '^mnd_[A-Za-z0-9]{26}$'),
  provider TEXT NOT NULL CHECK (provider = 'hyperswitch'),
  merchant_id TEXT NOT NULL CHECK (char_length(merchant_id) BETWEEN 1 AND 256),
  customer_id TEXT NOT NULL CHECK (char_length(customer_id) BETWEEN 1 AND 256),
  payment_method_id TEXT NOT NULL
    CHECK (char_length(payment_method_id) BETWEEN 1 AND 255 AND payment_method_id ~ '^[!-~]+$'),
  source_payment_id TEXT NOT NULL
    CHECK (char_length(source_payment_id) = 30 AND source_payment_id ~ '^pay_[A-Za-z0-9]{26}$'),
  source_event_id TEXT NOT NULL CHECK (char_length(source_event_id) BETWEEN 1 AND 255),
  consent_accepted_at TIMESTAMPTZ NOT NULL,
  consent_acceptance_type TEXT NOT NULL CHECK (consent_acceptance_type = 'online'),
  consent_scope TEXT NOT NULL CHECK (consent_scope = 'OFF_SESSION_RECURRING'),
  consent_terms_version TEXT NOT NULL CHECK (consent_terms_version = 'luckread-recurring-consent-v1'),
  provider_mandate_id TEXT CHECK (provider_mandate_id IS NULL OR char_length(provider_mandate_id) BETWEEN 1 AND 255),
  status TEXT NOT NULL CHECK (status IN ('PENDING_PROVIDER_CONFIRMATION','ACTIVE','REVOKED','FAILED','EXPIRED')),
  version BIGINT NOT NULL DEFAULT 1 CHECK (version >= 1),
  provider_updated_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL CHECK (updated_at >= created_at),
  UNIQUE (provider, merchant_id, source_payment_id),
  UNIQUE (provider, merchant_id, source_event_id),
  CHECK (
    (status = 'PENDING_PROVIDER_CONFIRMATION' AND provider_updated_at IS NULL)
    OR (status <> 'PENDING_PROVIDER_CONFIRMATION' AND provider_updated_at IS NOT NULL)
  )
);
CREATE UNIQUE INDEX ux_payment_mandates_provider_mandate_id
  ON payment_mandates(provider, merchant_id, provider_mandate_id)
  WHERE provider_mandate_id IS NOT NULL;
CREATE INDEX ix_payment_mandates_customer_status_created
  ON payment_mandates(customer_id, status, created_at, mandate_record_id);
CREATE INDEX ix_payment_mandates_method_status
  ON payment_mandates(provider, merchant_id, payment_method_id, status, updated_at);

CREATE FUNCTION w07_d104_saved_mandate_source_guard()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  CASE TG_ARGV[0]
    WHEN 'saved_payment_methods_require_succeeded_payment' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.payments p
        WHERE p.payment_id = NEW.source_payment_id
          AND p.provider = NEW.provider
          AND p.merchant_id = NEW.merchant_id
          AND p.customer_id = NEW.customer_id
          AND p.status = 'succeeded'
      ) OR NOT EXISTS (
        SELECT 1 FROM public.payment_provider_events e
        WHERE e.provider = NEW.provider
          AND e.merchant_id = NEW.merchant_id
          AND e.event_id = NEW.source_event_id
          AND e.payment_id = NEW.source_payment_id
          AND e.event_type = 'payment_succeeded'
          AND e.state = 'RECEIVED'
      ) THEN
        RAISE EXCEPTION 'saved payment method requires a succeeded customer-bound payment and verified event'
          USING ERRCODE = '23514';
      END IF;
    WHEN 'saved_payment_methods_customer_binding_guard' THEN
      IF EXISTS (
        SELECT 1 FROM public.saved_payment_methods existing
        WHERE existing.provider = NEW.provider
          AND existing.merchant_id = NEW.merchant_id
          AND existing.payment_method_id = NEW.payment_method_id
          AND existing.customer_id <> NEW.customer_id
      ) THEN
        RAISE EXCEPTION 'provider payment method cannot be rebound to another customer'
          USING ERRCODE = '23514';
      END IF;
    WHEN 'saved_payment_methods_identity_immutable' THEN
      IF NEW.saved_payment_method_id IS DISTINCT FROM OLD.saved_payment_method_id
        OR NEW.provider IS DISTINCT FROM OLD.provider
        OR NEW.merchant_id IS DISTINCT FROM OLD.merchant_id
        OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
        OR NEW.payment_method_id IS DISTINCT FROM OLD.payment_method_id
        OR NEW.source_payment_id IS DISTINCT FROM OLD.source_payment_id
        OR NEW.source_event_id IS DISTINCT FROM OLD.source_event_id
        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'saved payment method identity is immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'saved_payment_methods_retained' THEN
      RAISE EXCEPTION 'saved payment method audit records are retained' USING ERRCODE = '23514';
    WHEN 'payment_mandates_require_saved_method' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.saved_payment_methods m
        WHERE m.provider = NEW.provider
          AND m.merchant_id = NEW.merchant_id
          AND m.customer_id = NEW.customer_id
          AND m.payment_method_id = NEW.payment_method_id
      ) OR NOT EXISTS (
        SELECT 1 FROM public.payments p
        WHERE p.payment_id = NEW.source_payment_id
          AND p.provider = NEW.provider
          AND p.merchant_id = NEW.merchant_id
          AND p.customer_id = NEW.customer_id
          AND p.status = 'succeeded'
      ) OR NOT EXISTS (
        SELECT 1 FROM public.payment_provider_events e
        WHERE e.provider = NEW.provider
          AND e.merchant_id = NEW.merchant_id
          AND e.event_id = NEW.source_event_id
          AND e.payment_id = NEW.source_payment_id
          AND e.event_type = 'payment_succeeded'
          AND e.state = 'RECEIVED'
      ) THEN
        RAISE EXCEPTION 'mandate requires matching saved method, succeeded payment and verified event'
          USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_mandates_start_pending' THEN
      IF NEW.status <> 'PENDING_PROVIDER_CONFIRMATION'
        OR NEW.version <> 1
        OR NEW.provider_updated_at IS NOT NULL THEN
        RAISE EXCEPTION 'new mandates must await provider confirmation' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_mandates_identity_immutable' THEN
      IF NEW.mandate_record_id IS DISTINCT FROM OLD.mandate_record_id
        OR NEW.provider IS DISTINCT FROM OLD.provider
        OR NEW.merchant_id IS DISTINCT FROM OLD.merchant_id
        OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
        OR NEW.payment_method_id IS DISTINCT FROM OLD.payment_method_id
        OR NEW.source_payment_id IS DISTINCT FROM OLD.source_payment_id
        OR NEW.source_event_id IS DISTINCT FROM OLD.source_event_id
        OR NEW.consent_accepted_at IS DISTINCT FROM OLD.consent_accepted_at
        OR NEW.consent_acceptance_type IS DISTINCT FROM OLD.consent_acceptance_type
        OR NEW.consent_scope IS DISTINCT FROM OLD.consent_scope
        OR NEW.consent_terms_version IS DISTINCT FROM OLD.consent_terms_version
        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'mandate consent evidence and identity are immutable' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_mandates_version_guard' THEN
      IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'mandate update requires version CAS and increasing updated_at' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_mandates_transition_guard' THEN
      IF NOT (
        (OLD.status = 'PENDING_PROVIDER_CONFIRMATION' AND NEW.status IN ('PENDING_PROVIDER_CONFIRMATION','ACTIVE','REVOKED','FAILED','EXPIRED'))
        OR (OLD.status = 'ACTIVE' AND NEW.status IN ('ACTIVE','REVOKED','EXPIRED'))
        OR (OLD.status IN ('REVOKED','FAILED','EXPIRED') AND NEW.status = OLD.status)
      ) THEN
        RAISE EXCEPTION 'forbidden mandate status transition' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_mandates_provider_id_immutable' THEN
      IF OLD.provider_mandate_id IS NOT NULL AND NEW.provider_mandate_id IS DISTINCT FROM OLD.provider_mandate_id THEN
        RAISE EXCEPTION 'provider mandate ID cannot change after it is recorded' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_mandates_provider_timestamp_monotonic' THEN
      IF OLD.provider_updated_at IS NOT NULL AND NEW.provider_updated_at IS NOT NULL
        AND NEW.provider_updated_at <= OLD.provider_updated_at THEN
        RAISE EXCEPTION 'provider mandate timestamp must advance' USING ERRCODE = '23514';
      END IF;
    WHEN 'payment_mandates_retained' THEN
      RAISE EXCEPTION 'mandate audit records are retained' USING ERRCODE = '23514';
    ELSE
      RAISE EXCEPTION 'UNKNOWN_W07_D104_SAVED_MANDATE_TRIGGER_ACTION_%', TG_ARGV[0] USING ERRCODE = '55000';
  END CASE;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER saved_payment_methods_require_succeeded_payment
BEFORE INSERT ON saved_payment_methods
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('saved_payment_methods_require_succeeded_payment');
CREATE TRIGGER saved_payment_methods_customer_binding_guard
BEFORE INSERT ON saved_payment_methods
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('saved_payment_methods_customer_binding_guard');
CREATE TRIGGER saved_payment_methods_identity_immutable
BEFORE UPDATE OF saved_payment_method_id, provider, merchant_id, customer_id, payment_method_id, source_payment_id, source_event_id, created_at ON saved_payment_methods
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('saved_payment_methods_identity_immutable');
CREATE TRIGGER saved_payment_methods_retained
BEFORE DELETE ON saved_payment_methods
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('saved_payment_methods_retained');

CREATE TRIGGER payment_mandates_require_saved_method
BEFORE INSERT ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_require_saved_method');
CREATE TRIGGER payment_mandates_start_pending
BEFORE INSERT ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_start_pending');
CREATE TRIGGER payment_mandates_identity_immutable
BEFORE UPDATE OF mandate_record_id, provider, merchant_id, customer_id, payment_method_id, source_payment_id, source_event_id,
  consent_accepted_at, consent_acceptance_type, consent_scope, consent_terms_version, created_at
ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_identity_immutable');
CREATE TRIGGER payment_mandates_version_guard
BEFORE UPDATE ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_version_guard');
CREATE TRIGGER payment_mandates_transition_guard
BEFORE UPDATE OF status ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_transition_guard');
CREATE TRIGGER payment_mandates_provider_id_immutable
BEFORE UPDATE OF provider_mandate_id ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_provider_id_immutable');
CREATE TRIGGER payment_mandates_provider_timestamp_monotonic
BEFORE UPDATE OF provider_updated_at ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_provider_timestamp_monotonic');
CREATE TRIGGER payment_mandates_retained
BEFORE DELETE ON payment_mandates
FOR EACH ROW EXECUTE FUNCTION w07_d104_saved_mandate_source_guard('payment_mandates_retained');

COMMENT ON TABLE saved_payment_methods IS 'W07 D1-04 opaque provider token reference only; never persist PAN/CVC, API credentials or raw webhook body.';
COMMENT ON COLUMN saved_payment_methods.payment_method_id IS 'Sensitive opaque provider reference; internal-only, never expose via API or logs.';
COMMENT ON TABLE payment_mandates IS 'W07 D1-04 explicit immutable online recurring-consent evidence and provider mandate lifecycle; it never grants subscription entitlement.';
COMMENT ON COLUMN payment_mandates.consent_terms_version IS 'Immutable version of the exact online consent text accepted by the customer.';
